import {LEARNING} from './learning.mjs';
import {mountNetwork} from './network-view.mjs';
import {run,initial,clone,COMMANDS,ready,cidr,ipValid} from './engine.mjs';
import {QUESTS,CHAPTERS,goalResults,createLab} from './quests.mjs';
const $=s=>document.querySelector(s);
const liveNetwork=mountNetwork($('#topology'),{onCommand(c){$('#command').value=c;$('#command').focus()}});
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fresh=q=>({support:false,prediction:'',state:clone(q.init),evidence:{},logs:[],hint:0,trace:[],completed:false});
function read(key){try{return JSON.parse(localStorage.getItem(key))}catch{return null}}
const old=read('packetbound-v1'),saved=read('packetbound-v2');
let done=[...new Set((saved?.done||old?.done||[]).filter(n=>Number.isInteger(n)&&n>=0&&n<QUESTS.length))].sort((a,b)=>a-b);
// Only contiguous campaign completions unlock later chapters.
let unlocked=0;while(done.includes(unlocked)&&unlocked<QUESTS.length)unlocked++;
done=done.filter(n=>n<unlocked);
let current=Number.isInteger(saved?.current)?Math.max(0,Math.min(saved.current,Math.min(unlocked,17))):Math.min(old?.current||0,unlocked,17);
let selectedChapter=Math.floor(current/6),sessions={},lab=null,labMode=false,labCount=Number.isInteger(saved?.labCount)?saved.labCount:0;
function validState(s){return s&&typeof s.link==='boolean'&&(s.ip===null||cidr(s.ip))&&(s.gateway===null||ipValid(s.gateway))&&(s.dns===null||ipValid(s.dns))&&Array.isArray(s.routes)&&s.routes.every(r=>cidr(r.prefix)&&ipValid(r.via))&&Array.isArray(s.blocked)&&s.blocked.every(p=>Number.isInteger(p)&&p>0&&p<65536)&&(s.cache===null||ipValid(s.cache))}
if(saved?.sessions)for(const [k,v] of Object.entries(saved.sessions)){if(/^\d+$/.test(k)&&+k<QUESTS.length&&validState(v?.state))sessions[k]={...fresh(QUESTS[+k]),...v,logs:Array.isArray(v.logs)?v.logs.slice(-100).filter(l=>typeof l.text==='string'):[],evidence:v.evidence&&typeof v.evidence==='object'?v.evidence:{}}}
if(!saved&&old?.state){const st=initial(old.state);if(validState(st))sessions[current]={...fresh(QUESTS[current]),state:st}}
if(saved?.lab&&validState(saved.lab.state))lab={...fresh(QUESTS[17]),...saved.lab};
let history=[],historyIndex=0;
const labQuest={title:'未知の障害に挑む',place:'復旧訓練場',topic:'SANDBOX / ランダム演習',story:'3つの障害がランダムに発生している。正常な設計は192.168.10.20/24、出口192.168.10.1、DNS192.168.10.53。archive.net の /health を取得して復旧を報告しよう。答えは観測の中にある。',goals:['/health の200応答を取得し復旧を検証'],tools:['ip link','ip addr','ip route','ip neigh','resolvectl show-cache','sudo iptables -S OUTPUT','service status'],brief:'リンク・アドレス・経路・名前解決・ポート・サービスのどこまで正常かを確かめよう。',hint:'直接IPへの ping と名前での通信を比較。経路表、近隣表、DNSキャッシュ、送信規則、サーバー状態も確認しよう。',note:'手順を暗記した状態から、観測を選ぶ練習へ。失敗の原因を予測してからコマンドを打ち、予測との違いを説明してみよう。',lore:'シミュレーションは複雑な現実の一部をモデル化する。モデルの中での成功を、そのまま実機での万能な手順と考えないことが大切。',why:'復旧後には、どの観測がそれぞれの原因を示したかをログで振り返ろう。',xp:0};
function q(){return labMode?labQuest:QUESTS[current]}
function session(){if(labMode)return lab;return sessions[current]||(sessions[current]=fresh(QUESTS[current]))}
function effectiveEvidence(){const t=session(),e={...t.evidence},fingerprint=JSON.stringify(t.state);for(const key of Object.keys(e))if(/^(ping:|curl$|health$|root$|port-open:|port-filtered:)/.test(key))e[key]=e[key]===fingerprint;return e}
function results(){return labMode?[ready(session().state)&&Boolean(effectiveEvidence().health)]:goalResults(q(),session().state,effectiveEvidence())}
function save(){try{localStorage.setItem('packetbound-v2',JSON.stringify({done,current,sessions,lab,labCount}))}catch{$('.online').textContent='保存できません'}}
function log(text,kind='log'){const t=session();t.logs.push({text,kind});if(t.logs.length>100)t.logs.shift();const d=document.createElement('div');d.className='log '+kind;d.textContent=text;$('#output').append(d);$('#output').scrollTop=$('#output').scrollHeight}
function paintLogs(){$('#output').textContent='';const entries=[...session().logs];if(!entries.length){log('PACKETBOUND NETWORK OS v2 / '+q().place,'success');log('観測 → 仮説 → 変更 → 再確認。help で操作を確認できます。')}else for(const l of entries){const d=document.createElement('div');d.className='log '+(['success','error','command'].includes(l.kind)?l.kind:'');d.textContent=l.text;$('#output').append(d)}$('#output').scrollTop=$('#output').scrollHeight}
function maxOpen(){let i=0;while(done.includes(i))i++;return Math.min(i,17)}
function progress(){const xp=done.reduce((n,i)=>n+QUESTS[i].xp,0);$('#level').textContent=`Lv. ${1+done.length}　${xp} XP`;$('#progressText').textContent=`${done.length} / ${QUESTS.length}`;$('#progress').style.width=done.length/QUESTS.length*100+'%';$('#chapters').innerHTML=CHAPTERS.map((c,i)=>`<button class="chapter ${selectedChapter===i?'selected':''}" data-chapter="${i}"><span>0${i+1}　${c.title}</span><small>${done.filter(n=>Math.floor(n/6)===i).length}/6 ${i*6>maxOpen()?'⌑':''}</small></button>`).join('');document.querySelectorAll('[data-chapter]').forEach(b=>b.onclick=()=>{selectedChapter=+b.dataset.chapter;progress();drawMap()});$('#quests').innerHTML=QUESTS.filter(x=>x.chapter===selectedChapter).map(x=>`<button class="quest ${!labMode&&x.id===current?'selected':''}" data-quest="${x.id}" ${x.id>maxOpen()?'disabled':''}><span class="questNum">${done.includes(x.id)?'✓':String(x.id+1).padStart(2,'0')}</span><span><b>${x.title}</b><small>${x.topic.split(' / ')[0]}</small></span></button>`).join('');document.querySelectorAll('[data-quest]').forEach(b=>b.onclick=()=>select(+b.dataset.quest));$('#labTab').title=done.length<6?'第1章クリアで解放':'ランダムな3つの障害に挑戦'}
function update(){const t=session(),s=t.state,flags=results();$('#objectives').innerHTML=q().goals.map((g,i)=>`<div class="objective ${flags[i]?'met':''}"><span>${flags[i]?'✓':'◇'}</span>${g}</div>`).join('');$('#state').innerHTML=`<dt>eth0</dt><dd>${s.link?'UP':'DOWN'}</dd><dt>IPv4</dt><dd>${esc(s.ip||'未設定')}</dd><dt>gateway</dt><dd>${esc(s.gateway||'未設定')}</dd><dt>DNS</dt><dd>${esc(s.dns||'未設定')}</dd><dt>TCP 443</dt><dd>${s.firewall?'BLOCKED':'ALLOW'}</dd>`;$('#packetTrace').innerHTML=t.trace?.length?t.trace.map((step,i)=>`<span class="traceStep"><b>${i+1}</b>${esc(step)}</span>`).join(''):'通信コマンドを実行すると、処理の流れがここに表示されます。';$('#check').textContent=t.completed?(labMode?'別の障害に挑む →':current===17?'旅の記録を見る →':'次の地域へ進む →'):'復旧を検証する →';liveNetwork.setSupport(Boolean(t.support));liveNetwork.update(t.state);$('#state').hidden=!t.support;$('#questTools').hidden=!t.support;$('#supportToggle').textContent=t.support?'解説を閉じて調査へ':'機構・設定の解説を開く';save()}
function render(){$('#prediction').value=session().prediction||'';$('#reviewLesson').hidden=!session().completed;progress();$('#questTag').textContent=labMode?'TRAINING / INCIDENT':`QUEST ${String(current+1).padStart(2,'0')} / ${q().topic.split(' / ')[0]}`;$('#questTitle').textContent=q().title;$('#story').textContent=labMode?q().story:LEARNING[current][1];$('#questReward').textContent=labMode?'演習記録に追加':`✧ ${q().xp} XP${done.includes(current)?' / 獲得済み':''}`;$('#mentor').textContent=labMode?q().brief:'学習目標：'+LEARNING[current][0];$('#terminalTitle').textContent=q().place+' / traveler@node';$('#questTools').innerHTML='<small>調査の道具（クリックで入力）</small>'+q().tools.filter(c=>!/^sudo (?!iptables -S)|^service start|^dns set|^fw |^dhcp /.test(c)).map(c=>`<button class="commandChip" data-command="${esc(c)}">${esc(c)}</button>`).join('');bindChips();$('#feedback').textContent='';$('#hint').hidden=true;$('#moreHint').hidden=true;$('#hintButton').innerHTML='◈ 段階ヒント <span>＋</span>';drawMap();paintLogs();update();renderTopology()}
function bindChips(){document.querySelectorAll('[data-command]').forEach(b=>b.onclick=()=>{$('#command').value=b.dataset.command;$('#command').focus();if($('#modal').open)$('#modal').close()})}
function select(i){if(i>maxOpen())return;current=i;selectedChapter=Math.floor(i/6);labMode=false;render()}
function drawMap(){const chapter=CHAPTERS[selectedChapter];$('h1').innerHTML=esc(chapter.map)+'<span> / CHAPTER 0'+(selectedChapter+1)+'</span>';let trees='';for(let i=0;i<65;i++){const x=155+(i*97%590),y=180+(i*53%170);trees+=`<path d="M${x} ${y}l-6 12h12z M${x} ${y+8}l-8 13h16z"/>`}$('#trees').innerHTML=trees;$('#world').style.filter=selectedChapter===1?'hue-rotate(38deg)':selectedChapter===2?'hue-rotate(-20deg)':'none';$('#nodes').innerHTML=QUESTS.filter(x=>x.chapter===selectedChapter).map(x=>{const [a,b]=x.pos,active=!labMode&&x.id===current,c=done.includes(x.id)?'#c4e68d':active?'#d9d7a0':'#81917b';return `<g class="node" role="button" tabindex="0" aria-label="${esc(x.place)}${x.id>maxOpen()?' 未解放':''}" data-node="${x.id}" transform="translate(${a} ${b})"><ellipse rx="36" ry="16" cy="17" fill="#0b120f" opacity=".6"/>${active?'<circle class="pulse" r="38" fill="none" stroke="#c4e68d" stroke-opacity=".6"/>':''}<path d="M-23 14V-12L-11-23 0-12 12-31 24-17V14Z" fill="#324332" stroke="${c}" stroke-width="2"/><path d="M-23-12h23M0-12l12-19M8 14V-4h8v18M-16 0h7v8h-7" stroke="${c}" fill="#172219"/><circle r="4" cy="-42" fill="${c}"/><rect x="-72" y="33" width="144" height="28" rx="4" fill="#121b15" stroke="${active?'#72865b':'#334334'}"/><text y="51" text-anchor="middle" fill="${c}" font-size="12">${done.includes(x.id)?'✓ ':''}${esc(x.place)}</text></g>`}).join('');document.querySelectorAll('[data-node]').forEach(n=>{const travel=()=>{const i=+n.dataset.node;if(i<=maxOpen())select(i);else{$('#feedback').textContent='前のクエストを完了すると、この地域が解放されます。'}};n.onclick=travel;n.onkeydown=e=>{if(['Enter',' '].includes(e.key)){e.preventDefault();travel()}}});$('#mapStatus').textContent=`${chapter.title}　${done.filter(i=>Math.floor(i/6)===selectedChapter).length}/6 復旧`}
function renderTopology(){liveNetwork.reset(session().state)}
function execute(raw){const c=raw.trim().replace(/\s+/g,' ');if(!c)return;history.push(c);historyIndex=history.length;log('traveler@node:~$ '+c,'command');if(c==='clear'){session().logs=[];$('#output').textContent='';save();return}if(c==='mission'){log((labMode?q().story:LEARNING[current][1])+'\n\n'+q().goals.join('\n'));save();return}const r=run(session().state,c);for(const event of r.events){session().evidence[event]=/^(ping:|curl$|health$|root$|port-open:|port-filtered:)/.test(event)?JSON.stringify(session().state):true}log(r.text,r.kind);if(r.steps.length)session().trace=r.steps;if(r.changed)session().completed=false;update();if(session().support)liveNetwork.command(session().state,c,r)}
$('#commandForm').onsubmit=e=>{e.preventDefault();execute($('#command').value);$('#command').value=''};
$('#command').onkeydown=e=>{if(e.key==='ArrowUp'||e.key==='ArrowDown'){e.preventDefault();historyIndex=Math.max(0,Math.min(history.length,historyIndex+(e.key==='ArrowUp'?-1:1)));e.target.value=history[historyIndex]||''}if(e.key==='Tab'){e.preventDefault();const match=COMMANDS.map(x=>x[0]).find(c=>c.startsWith(e.target.value));if(match)e.target.value=match}};
function modal(html){$('#modalContent').innerHTML=html;if(!$('#modal').open)$('#modal').showModal()}
$('#closeModal').onclick=()=>$('#modal').close();$('#modal').onclick=e=>{if(e.target===$('#modal'))$('#modal').close()};
$('#check').onclick=()=>{if(session().completed){if(labMode)newLab();else if(current<17)select(current+1);else journal();return}if(!results().every(Boolean)){$('#feedback').textContent='未達成の条件（◇）を確認してください。設定を変えた後は、通信確認をもう一度実行しましょう。';return}session().completed=true;if(labMode){if(!session().awarded){labCount++;session().awarded=true}}else if(!done.includes(current))done.push(current);progress();drawMap();update();const ending=labMode?'ランダム演習をクリア。':(current%6===5?'章クリア！ 称号「'+CHAPTERS[Math.floor(current/6)].badge+'」を獲得。':'復旧を確認。次の地域が解放されました。');$('#feedback').textContent=ending+' '+q().why;log('QUEST COMPLETE — '+q().place,'success');log('振り返り: '+q().why);$('#reviewLesson').hidden=labMode;save()};
function reflect(){
 const lesson=LEARNING[current];
 modal('<div class="eyebrow">TRANSFER / 別の状況でも説明できる？</div><h2>'+esc(lesson[2])+'</h2><p>まず自分の言葉で説明してみよう。今回のログのどの結果が、その説明の根拠になる？</p><textarea id="reasoning" rows="4" placeholder="観測したこと → そこから言えること"></textarea><button class="primary" id="compareReason">解説と照合する</button><div id="reasonFeedback"></div>');
 $('#reasoning').value=session().reasoning||'';
 $('#reasoning').oninput=e=>{session().reasoning=e.target.value;save()};
 $('#compareReason').onclick=()=>{$('#reasonFeedback').textContent=lesson[3]+'　自分の説明と比べ、観測した事実と推測を区別できているか確認しよう。自由記述は自動採点していません。'};
}
function showHint(){const t=session();t.hint=Math.max(1,Math.min(3,t.hint));$('#hint').hidden=false;$('#hint').textContent=`HINT ${t.hint}/3\n`+(t.hint===1?(labMode?q().brief:'観測する前に、結果がどうなるか予想しよう。'+LEARNING[current][0]):t.hint===2?q().hint:labMode?'既知の正常設定へ復旧しよう。ip link / ip addr / ip route / ip neigh / resolvectl show-cache / sudo iptables -S OUTPUT / service status の観測結果を順番に確認。ランダム演習では固定の解答はありません。':q().solution.join('\n'));$('#moreHint').hidden=t.hint>=3;$('#hintButton').innerHTML='◈ ヒントを閉じる <span>−</span>';save()}
$('#hintButton').onclick=()=>{if(!$('#hint').hidden){$('#hint').hidden=true;$('#moreHint').hidden=true;$('#hintButton').innerHTML='◈ 段階ヒント <span>＋</span>'}else showHint()};$('#moreHint').onclick=()=>{session().hint++;showHint()};
$('#clear').onclick=()=>{session().logs=[];$('#output').textContent='';save();$('#command').focus()};
function noteContent(x){return `<div class="eyebrow">FIELD NOTE / ${esc(x.topic)}</div><h2>${esc(x.title)}</h2><p>${esc(x.note)}</p><h3>観測の着眼点</h3><p>${esc(x.why)}</p><h3>言葉の小話</h3><p>${esc(x.lore)}</p><h3>このモデルの限界</h3><p>ブラウザ内の状態モデルです。実パケット、ARPの時間変化、DHCP更新・期限、TCP再送、実際の遅延、TLS内部処理は再現しません。表示する経路・パケットの流れは説明用です。</p>`}
$('#notes').onclick=()=>modal(noteContent(q()));
function journal(){modal(`<div class="eyebrow">NETWORKER’S JOURNAL</div><h2>旅で手に入れた知識</h2><div class="badges">${CHAPTERS.map((x,i)=>`<span class="badge ${done.filter(n=>Math.floor(n/6)===i).length===6?'earned':''}">✧ ${x.badge}</span>`).join('')}</div><p>キャンペーン ${done.length}/18 完了 ・ ランダム演習 ${labCount} 回復旧</p><div class="journalList">${QUESTS.map(x=>`<button data-note="${x.id}"><span>${done.includes(x.id)?'✓':'◇'} ${String(x.id+1).padStart(2,'0')}　${x.title}</span><small>${x.topic}</small></button>`).join('')}</div>`);document.querySelectorAll('[data-note]').forEach(b=>b.onclick=()=>{modal(noteContent(QUESTS[+b.dataset.note])+'<button class="textbutton" id="backJournal">← 図鑑へ戻る</button>');$('#backJournal').onclick=journal})}
$('#journalTab').onclick=journal;
$('#commandBook').onclick=()=>{modal('<div class="eyebrow">COMMAND REFERENCE</div><h2>調査と復旧の道具</h2><p>クリックすると端末に入力されます。内容を読んでから Enter で実行してください。※はゲーム用の簡略操作です。</p><div class="commandList">'+COMMANDS.map(([c,n])=>`<button data-command="${esc(c)}"><code>${esc(c)}</code><span>${esc(n)}</span></button>`).join('')+'</div>');bindChips()};
$('#guideTab').onclick=()=>modal('<div class="eyebrow">ADVENTURER’S HANDBOOK / EXPANSION 02</div><h2>観測する力が、世界をつなぐ。</h2><p>情報工学のコンピュータネットワークを、3章18クエストで学びます。第1章は通信の基礎、第2章はARP・DHCP・CIDR・経路・キャッシュ・TTL、第3章はTCP・HTTP・通信方針と複合障害です。</p><ol><li>物語と正常なネットワーク構成を読む。</li><li>コマンドで状態を観測し、原因の仮説を立てる。</li><li>設定を変え、指定された通信を試す。</li><li>達成条件がすべて ✓ になったら、復旧を検証。</li></ol><p>道具ボタンは入力だけを行います。実行は Enter。↑↓で履歴、Tabで補完。段階ヒントにペナルティはありません。第1章クリア後はランダム演習も利用できます。</p><h3>進行と再挑戦</h3><p>各クエストの設定・ログ・進行をこのブラウザに保存します。地域を移動しても続きから再開できます。「やり直す」はそのクエストだけ初期化し、獲得済みXPは保持します。再クリアでXPは重複しません。以前の6クエストのクリア履歴も引き継ぎます。</p><h3>実機との違い</h3><p>実際のOSを変更せず、外部ホストにも通信しません。コマンドは限定的な構文だけに対応。DNSにはsystemd-resolvedのresolvectl、送信規則にはiptables、DHCPにはdhclientを使う構成を想定します。実機では環境によって利用できるツールが異なります。ip addr replaceは単一アドレスを扱う簡略モデルです。書庫の管理用service status / service start httpsとmissionはゲーム内の操作です。</p>');
function newLab(){lab={...fresh(QUESTS[17]),state:createLab()};labMode=true;render()}
$('#labTab').onclick=()=>{if(done.length<6){modal('<h2>実践訓練は第1章クリアで解放</h2><p>基礎の6クエストを終えると、3つのランダムな障害を調べる訓練場に進めます。何度でも別の組み合わせに挑戦できます。</p>');return}if(lab){labMode=true;render()}else newLab()};
$('#retry').onclick=()=>{modal('<h2>この演習をやり直す？</h2><p>現在の演習の設定とログを初期化します。獲得済みXPとクリア履歴は残ります。ランダム演習は新しい障害になります。</p><button class="primary" id="confirmRetry">やり直す</button>');$('#confirmRetry').onclick=()=>{if(labMode)newLab();else{sessions[current]=fresh(QUESTS[current]);render()}$('#modal').close()}};
$('#reset').onclick=()=>{modal('<h2>すべての進行をリセット？</h2><p>全クエストの進行・XP・ログ・演習記録を削除して最初から始めます。</p><button class="primary" id="confirmReset">すべてリセットする</button>');$('#confirmReset').onclick=()=>{done=[];sessions={};lab=null;labCount=0;select(0);$('#modal').close()}};
$('#mapView').onclick=()=>{liveNetwork.pause();$('.terminal').append($('#commandForm'));$('#topology').hidden=true;$('#map').hidden=false;$('#mapView').classList.add('active');$('#topologyView').classList.remove('active')};$('#topologyView').onclick=()=>{$('#topology .liveHeading').after($('#commandForm'));$('#topology').hidden=false;$('#map').hidden=true;$('#topologyView').classList.add('active');$('#mapView').classList.remove('active')};
$('#worldTab').onclick=()=>{if(labMode)select(current);$('#mapView').click();$('.center').scrollIntoView({behavior:'smooth',block:'start'})};
$('#supportToggle').onclick=()=>{session().support=!session().support;session().supportUsed ||= session().support;renderTopology();update()};
$('#prediction').oninput=e=>{session().prediction=e.target.value;save()};
$('#reviewLesson').onclick=reflect;
render();
$('#topologyView').click();
